cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and single base premiums ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");
  it.todo("quotes a plain sword -- base 100 G + 5 G fee = 105 G");
  it.todo("quotes a plain amulet -- base 60 G + 5 G fee = 65 G");
  it.todo("quotes a plain staff -- base 80 G + 5 G fee = 85 G");
  it.todo("quotes a plain potion -- base 40 G + 5 G fee = 45 G");
  it.todo("quotes a single rune -- base 25 G + 5 G fee = 30 G");
  it.todo("quotes a single moonstone -- base 25 G + 5 G fee = 30 G");

  // --- Component building blocks (block of exactly 3 alike) ---
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block: block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block: 7 is not exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types are not alike)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks, alike = same type)");

  // --- Item-specific modifiers ---
  it.todo("quotes a cursed sword -- base 100 G + 50 G curse surcharge (50%)");
  it.todo("quotes a sword with enchantment 5 -- base 100 G + 30 G high-enchantment surcharge (threshold is >= 5)");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quotes a cursed sword with enchantment 5 -- both surcharges apply: 100 + 50 + 30");
  it.todo("applies item-specific surcharges only to the affected item's base premium -- cursed sword + plain amulet: base 160 G, curse adds 50 G (50% of the sword's 100 G) = 210 G before policy modifiers and fee");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20% loyalty discount to the policy base premium for a customer with exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO");
  it.todo("applies a 10% first-insurance surcharge to the policy base premium on the customer's first quote");
  it.todo("applies a 15% follow-up-contract discount on each contract after the first");
  it.todo("applies the first-insurance surcharge to every quote's items regardless of customer history -- each item in a quote is treated as a first insurance");

  // --- Rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (rounded in MHPCO's favor)");
  it.todo("rounds a payout of 350.5 G down to 350 G (rounded in MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote integration examples ---
  it.todo("integration: newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote errors ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- CLI exits non-zero, writes an error description to stderr, and writes no results to stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy payout at twice the insurance sum -- sword + amulet: insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword (premium 165 G): insurance sum 1000 G, cap 2000 G");
  it.todo("excludes the block discount from the insurance sum -- sword + 3 runes: insurance sum 1750 G, cap 3500 G");
  it.todo("sums insurance values for two swords -- insurance sum 2000 G, cap 4000 G");

  // --- Claim: deductible and standard reimbursement ---
  it.todo("reimburses a regular steel sword enchantment 3 with damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("reimburses a damaged rune (no enchantment, no material) with damage 200 G -- payout 100 G (full minus 100 G deductible)");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G in one incident = payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment >= 8 at 50% -- steel sword enchantment 9, damage 1000 G: payout 400 G (500 minus deductible)");
  it.todo("fully reimburses damage to a dragon-material item -- dragon sword enchantment 5, damage 800 G: payout 700 G (800 minus deductible)");
  it.todo("lets the 50% high-enchantment rule win when both clauses apply -- dragon sword enchantment 9, damage 1000 G: payout 400 G");
  it.todo("applies the high-enchantment clause at exactly enchantment 8 -- dragon sword enchantment 8, damage 1000 G: payout 400 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damage entry of the same item type as a separate damage with its own deductible -- two insured swords, two sword damages");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- CLI exits non-zero and writes an error description to stderr");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("reports the remaining cap after a claim -- sword (cap 2000 G), claim 1500 G: payout 1400 G, remainingCap 600 G");
  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G on the same policy: payout 600 G, remainingCap 0 G");

  // --- Claim errors ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero and writes an error description to stderr");
  it.todo("rejects a claim whose damage entry has an unknown item type -- CLI exits non-zero and writes an error description to stderr");
  it.todo("rejects a claim containing a damage entry with a negative amount (-200) -- CLI exits non-zero and writes an error description to stderr");

  // --- CLI adapter ---
  it.todo("reads a scenario from stdin and writes one result per step in order to stdout -- schema example: quote then claim on policy 0");
  it.todo("processes steps sequentially so a claim step refers to the policy created by the quote step at its zero-based index");
});
EOF
pnpm test 2>&1 | tail -12

