export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

const PRICE_LIST: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];

function basePremiumFor(item: Item): number {
  return PRICE_LIST[item.type];
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function basePremiumForAlikeComponents(type: string, count: number): number {
  if (count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_BASE_PREMIUM;
  }
  return count * PRICE_LIST[type];
}

export function policyBasePremium(items: Item[]): number {
  const components = items.filter((item) => COMPONENT_TYPES.includes(item.type));
  const mainItems = items.filter(
    (item) => !COMPONENT_TYPES.includes(item.type),
  );

  let total = mainItems.reduce((sum, item) => sum + basePremiumFor(item), 0);
  for (const [type, count] of countByType(components)) {
    total += basePremiumForAlikeComponents(type, count);
  }
  return total;
}

export function quote(customer: Customer, items: Item[]): number {
  return policyBasePremium(items) + PROCESSING_FEE;
}
