  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_INSURANCE_VALUE = 250;
const COMPONENT_BASE_PREMIUM = 25;

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_FACTOR = 2;''')
# replace the scenario section wholesale
head, sep, _tail = s.partition('export interface QuoteStep {')
s = head + '''export function insuranceValueFor(item: Item): number {
  return isComponent(item)
    ? COMPONENT_INSURANCE_VALUE
    : MAIN_ITEM_INSURANCE_VALUES[item.type];
}

/** The insurance sum is the sum of the items' insurance values. */
export function insuranceSum(items: Item[]): number {
  return items.reduce((total, item) => total + insuranceValueFor(item), 0);
}

export interface Damage {
  itemType: string;
  amount: number;
}

/** All amounts are rounded to whole G in the MHPCO's favor. */
function roundPayoutInMhpcoFavor(payout: number): number {
  return Math.floor(payout);
}

function reimbursementFor(damage: Damage): number {
  return damage.amount - DEDUCTIBLE_PER_DAMAGE;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

interface Policy {
  items: Item[];
  remainingCap: number;
}

export function runScenario(scenario: Scenario): { results: StepResult[] } {
  // Each quote is a contract; later ones are follow-up contracts.
  let previousContracts = 0;
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index): StepResult => {
    if (step.op === "quote") {
      const premium = quote(scenario.customer, step.items, previousContracts);
      previousContracts += 1;
      policies.set(index, {
        items: step.items,
        remainingCap: insuranceSum(step.items) * CAP_FACTOR,
      });
      return { premium };
    }

    const policy = policies.get(step.policy);
    if (policy === undefined) {
      throw new Error(`No policy was created by step ${String(step.policy)}`);
    }

    const desired = step.incident.damages.reduce(
      (total, damage) => total + reimbursementFor(damage),
      0,
    );
    const payout = roundPayoutInMhpcoFavor(Math.min(desired, policy.remainingCap));
    policy.remainingCap -= payout;
    return { payout, remainingCap: policy.remainingCap };
  });

  return { results };
}
'''
